"""Builds a downloadable PDF health report for one animal using fpdf2.

Note: the built-in PDF font only supports Latin letters. Hindi and Kannada text
is replaced with "?" so the PDF still opens. Translated PDFs would need a Unicode font file.
"""
import json
from datetime import date, timedelta

from fpdf import FPDF
from sqlalchemy.orm import Session

from backend import models as m
from backend.services.herd import animal_to_dict

DISCLAIMER = (
    "This report is generated by an AI-assisted farm tool from farm records. "
    "It is not a veterinary diagnosis. Please consult a veterinarian for any health concern."
)


def _safe(value) -> str:
    text = "-" if value is None else str(value)
    return text.encode("latin-1", "replace").decode("latin-1")


def _cut(value, width: int) -> str:
    text = _safe(value)
    return text if len(text) <= width else text[: width - 3] + "..."


def build_vet_report(db: Session, animal: m.Animal) -> bytes:
    detail = animal_to_dict(animal)
    indicator = detail["health_indicator"]
    today = date.today()

    health = sorted(animal.health_records, key=lambda r: r.recorded_at, reverse=True)[:10]
    milk = sorted(animal.milk_records, key=lambda r: r.recorded_on, reverse=True)
    milk_14 = [r for r in milk if (today - r.recorded_on).days <= 13]
    breeding = sorted(animal.breeding_records, key=lambda r: r.event_date, reverse=True)

    actions = [
        a for a in db.query(m.ProposedAction).order_by(m.ProposedAction.id.desc()).all()
        if json.loads(a.parameters_json or "{}").get("target") == f"animal:{animal.tag_id}"
    ]

    pdf = FPDF()
    pdf.set_auto_page_break(auto=True, margin=15)
    pdf.add_page()

    def title(text):
        pdf.set_font("Helvetica", "B", 16)
        pdf.cell(0, 10, _safe(text), new_x="LMARGIN", new_y="NEXT")

    def heading(text):
        pdf.ln(3)
        pdf.set_font("Helvetica", "B", 12)
        pdf.cell(0, 8, _safe(text), new_x="LMARGIN", new_y="NEXT")

    def body(text):
        pdf.set_font("Helvetica", "", 10)
        pdf.multi_cell(0, 6, _safe(text), new_x="LMARGIN", new_y="NEXT")

    def row(cells, widths, bold=False):
        pdf.set_font("Helvetica", "B" if bold else "", 9)
        for cell, width in zip(cells, widths):
            pdf.cell(width, 7, _cut(cell, int(width / 2)), border=1)
        pdf.ln(7)

    title("Veterinary Health Report")
    body(f"Generated on {today.isoformat()}. Data source: {animal.data_source}.")
    body(DISCLAIMER)

    heading("Animal details")
    body(f"Name: {animal.name}    Tag: {animal.tag_id}    Breed: {animal.breed}")
    body(f"Sex: {animal.sex}    Age: {animal.age_months} months    "
         f"Lactating: {'yes' if animal.lactating else 'no'}    Monitored: {'yes' if animal.is_monitored else 'no'}")

    heading(f"Current health status: {indicator['color'].upper()}")
    for line in indicator["explanations"]:
        body(f"- {line}")

    heading("Health history (latest 10 checks)")
    widths = [45, 30, 30, 85]
    row(["Date", "Temp (C)", "Severity", "Symptoms"], widths, bold=True)
    if not health:
        body("No health checks recorded.")
    for record in health:
        row([record.recorded_at.strftime("%Y-%m-%d %H:%M"),
             record.temperature_c, record.severity, record.symptoms or record.notes],
            widths)

    heading("Milk production (last 14 days)")
    if milk_14:
        average = sum(r.liters for r in milk_14) / len(milk_14)
        body(f"Average: {average:.1f} litres per day over {len(milk_14)} recorded day(s).")
        widths = [60, 40]
        row(["Date", "Litres"], widths, bold=True)
        for record in milk_14:
            row([record.recorded_on.isoformat(), f"{record.liters:.1f}"], widths)
    else:
        body("No milk records in the last 14 days.")

    heading("Breeding history")
    if breeding:
        widths = [40, 40, 100]
        row(["Date", "Event", "Notes"], widths, bold=True)
        for event in breeding[:10]:
            row([event.event_date.isoformat(), event.event_type, event.notes or "-"], widths)
    else:
        body("No breeding records.")

    heading("Recommendations")
    color = indicator["color"]
    if color == "red":
        body("- Arrange a veterinary examination as soon as possible.")
    elif color == "yellow":
        body("- Check temperature and milk yield daily and call a veterinarian if they worsen.")
    else:
        body("- Continue routine monitoring.")
    for action in actions[:5]:
        body(f"- Proposed action ({action.status}): {action.description}")

    return bytes(pdf.output())
